if (empty($_SESSION['is_admin'])) { header('Location: /index.php'); exit; }
?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Кошелёк — администрирование</title>
<style>body{margin:0;background:#f3f6fb;color:#172033;font:16px system-ui,sans-serif}.wrap{max-width:1000px;margin:35px auto;padding:0 16px}.card{background:#fff;border:1px solid #e1e7f0;border-radius:14px;padding:20px;margin:14px 0}h1{margin:0}h2{font-size:19px}input,select,button{font:inherit;padding:9px;border:1px solid #cdd5e1;border-radius:8px}button{background:#185abd;color:#fff;border:0;cursor:pointer}button:disabled{opacity:.5}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.field{display:grid;gap:5px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px 6px;border-bottom:1px solid #edf0f5}#msg{white-space:pre-wrap;margin:10px 0}.actions{display:flex;gap:6px;flex-wrap:wrap}.reject{background:#b42318}.muted{color:#667085}</style></head><body><main class="wrap"><h1>Ручное пополнение и тарифы</h1><p class="muted">Заявки подтверждаются вручную. Одобренная заявка зачисляется один раз.</p><div id="msg" role="status"></div>
<section class="card"><h2>Настройки</h2><form id="settings" class="row"><label class="field">Монет за 1 ₽<input id="rate" type="number" min="1" max="100000" required></label><label class="field">Цена дня подписки (монеты)<input id="price" type="number" min="1" max="1000000" required></label><button>Сохранить настройки</button></form></section>
<section class="card"><h2>Заявки на пополнение</h2><div class="row"><label class="field">Статус<select id="status"><option value="pending">Ожидают</option><option value="approved">Одобрены</option><option value="rejected">Отклонены</option><option value="all">Все</option></select></label><button id="reload">Обновить</button></div><div style="overflow:auto"><table><thead><tr><th>#</th><th>Пользователь</th><th>Сумма</th><th>Монет</th><th>Статус</th><th>Создана</th><th>Примечание</th><th>Действие</th></tr></thead><tbody id="requests"><tr><td colspan="8">Загрузка…</td></tr></tbody></table></div></section><p><a href="/admin.php">Вернуться в панель администратора</a></p></main>
<script>
let csrf='';async function api(url,opts={}){const headers={'Accept':'application/json',...(opts.headers||{})};if(opts.body){headers['Content-Type']='application/json';headers['X-CSRF-Token']=csrf;}const r=await fetch(url,{credentials:'same-origin',...opts,headers});const d=await r.json();if(!r.ok||d.success===false)throw new Error(d.message||'Ошибка запроса');if(d.csrf_token)csrf=d.csrf_token;return d;}
function td(tr,text){const e=document.createElement('td');e.textContent=text??'';tr.appendChild(e);return e;}
async function loadSettings(){const s=await api('/admin/wallet.php?action=settings');document.getElementById('rate').value=s.coins_per_ruble;document.getElementById('price').value=s.price_per_day;}
async function loadRequests(){const d=await api('/admin/wallet.php?action=requests&status='+encodeURIComponent(document.getElementById('status').value));const body=document.getElementById('requests');body.replaceChildren();if(!d.requests.length){const tr=body.insertRow();const e=tr.insertCell();e.colSpan=8;e.textContent='Заявок нет';return;}for(const x of d.requests){const tr=body.insertRow();td(tr,x.id);td(tr,x.user_email);td(tr,String(x.amount_rub)+' ₽');td(tr,String(x.requested_coins));td(tr,x.status);td(tr,x.created_at);td(tr,x.admin_note||'');const act=td(tr,'');if(x.status==='pending'){const wrap=document.createElement('div');wrap.className='actions';for(const [label,decision,cls] of [['Начислить','approve',''],['Отклонить','reject','reject']]){const b=document.createElement('button');b.textContent=label;if(cls)b.className=cls;b.addEventListener('click',()=>review(x.id,decision));wrap.appendChild(b);}act.appendChild(wrap);}else act.textContent='—';}}
async function review(id,decision){if(!confirm(decision==='approve'?'Подтвердить оплату и начислить монеты?':'Отклонить заявку?'))return;const note=prompt('Комментарий (необязательно):')||'';try{await api('/admin/wallet.php?action=review',{method:'POST',body:JSON.stringify({id,decision,note})});document.getElementById('msg').textContent='Заявка обработана.';await loadRequests();}catch(e){document.getElementById('msg').textContent=e.message;}}
document.getElementById('settings').addEventListener('submit',async e=>{e.preventDefault();try{await api('/admin/wallet.php?action=settings',{method:'POST',body:JSON.stringify({coins_per_ruble:Number(document.getElementById('rate').value),price_per_day:Number(document.getElementById('price').value)})});document.getElementById('msg').textContent='Настройки сохранены.';}catch(err){document.getElementById('msg').textContent=err.message;}});
document.getElementById('reload').addEventListener('click',()=>loadRequests().catch(e=>document.getElementById('msg').textContent=e.message));document.getElementById('status').addEventListener('change',()=>loadRequests().catch(e=>document.getElementById('msg').textContent=e.message));
Promise.all([loadSettings(),loadRequests()]).catch(e=>document.getElementById('msg').textContent=e.message);
</script></body></html>